(function(){const e=document.createElement("link").relList;if(e&&e.supports&&e.supports("modulepreload"))return;for(const o of document.querySelectorAll('link[rel="modulepreload"]'))d(o);new MutationObserver(o=>{for(const r of o)if(r.type==="childList")for(const s of r.addedNodes)s.tagName==="LINK"&&s.rel==="modulepreload"&&d(s)}).observe(document,{childList:!0,subtree:!0});function i(o){const r={};return o.integrity&&(r.integrity=o.integrity),o.referrerPolicy&&(r.referrerPolicy=o.referrerPolicy),o.crossOrigin==="use-credentials"?r.credentials="include":o.crossOrigin==="anonymous"?r.credentials="omit":r.credentials="same-origin",r}function d(o){if(o.ep)return;o.ep=!0;const r=i(o);fetch(o.href,r)}})();document.addEventListener("DOMContentLoaded",()=>{const t=document.querySelector(".burger-btn"),e=document.querySelector(".mobile-menu"),i=document.querySelector(".btn-menu-close");if(!t||!e||!i){console.warn("Елементи меню не знайдені");return}t.addEventListener("click",()=>{e.classList.add("is-open"),document.body.style.overflow="hidden"});const d=()=>{e.classList.remove("is-open"),document.body.style.overflow=""};i.addEventListener("click",d),e.addEventListener("click",o=>{o.target.tagName==="A"&&d()})});document.addEventListener("DOMContentLoaded",()=>{if(!window.location.pathname.endsWith("/")&&!window.location.pathname.endsWith("index.html"))return;const t=document.querySelector(".h-brands");if(!t)return;const e=new IntersectionObserver(i=>{i.forEach(d=>{d.isIntersecting&&(t.classList.add("animate"),e.unobserve(d.target))})},{threshold:.4});e.observe(t)});const a=[{q:["болить зуб","ниє зуб","зубний біль","болючий зуб"],a:{short:"Зубний біль може свідчити про карієс або пульпіт.",medium:"Біль може бути через карієс, пульпіт або запалення ясен. Тимчасово уникайте гарячого/холодного, не жуйте на хворий бік.",detailed:"Зубний біль часто спричинений карієсом, пульпітом, тріщинами емалі або запаленням ясен. Тимчасово: прийміть дозволене знеболююче, уникайте гарячого/холодного, не жуйте на уражений зуб. Остаточно проблему усуває тільки стоматологічне лікування — пломбування, лікування каналів або професійна чистка."}},{q:["пульсуючий біль","стріляє зуб","болить вночі"],a:{short:"Пульсуючий біль часто свідчить про пульпіт.",medium:"Пульсуючий біль або біль уночі може бути ознакою запалення нерва. Лікування каналів — основний метод.",detailed:"Пульсуючий зубний біль, особливо вночі, зазвичай означає пульпіт — запалення нерва зуба. Не можна затягувати з візитом: лікування каналів з дезінфекцією та пломбуванням забезпечує збереження зуба і зменшує ризик абсцесу. Тимчасово: прийняти дозволене знеболююче, уникати гарячого/холодного та тиску на зуб."}},{q:["боляче натискати","біль при жуванні","болить прикус"],a:{short:"Біль при жуванні може свідчити про періодонтит або тріщину зуба.",medium:"Біль на натискання пов’язана з періодонтитом, тріщиною кореня або проблемною пломбою. Тимчасово не жуйте на цей бік.",detailed:"Біль при натисканні або прикусуванні часто сигналізує про періодонтит, тріщину кореня або підняття пломби/коронки. Для діагностики потрібно рентгенівське обстеження та візит до стоматолога. Тимчасові заходи: не жуйте на уражений бік, можна полоскати рот теплою водою без спиртових розчинів, приймати дозволене знеболююче. Лікування включає пломбування, каналотерапію або реставрацію коронки."}},{q:["чутливість зубів","болить від холодного","зуб реагує на холод"],a:{short:"Чутливість зубів часто через оголення шийки або карієс.",medium:"Біль на холодне може бути через стирання емалі, демінералізацію або початковий карієс. Лікування — ремінералізація або пломбування.",detailed:"Чутливість зубів на холодні продукти може виникати через оголення шийки зуба, стирання емалі, початковий карієс або після професійного чищення. Тимчасові заходи: пасти для чутливих зубів, уникати дуже холодного/кислого, дотримуватися м’якої щітки. Лікування: ремінералізація фторовмісними препаратами, герметизація фісур або пломбування. Регулярні огляди допомагають вчасно виявляти початкові проблеми."}},{q:["набряк","флюс","гній","припухлість"],a:{short:"Набряк або флюс — ознака інфекції, потрібен лікар.",medium:"Набряк або флюс сигналізує про інфекцію (абсцес, загострений періодонтит). Не гріти! Зверніться до стоматолога.",detailed:"Набряк обличчя або флюс виникає через бактеріальну інфекцію, найчастіше внаслідок ускладненого карієсу або пульпіту. Зігрівати уражене місце заборонено, щоб не спровокувати поширення інфекції. Можна прикладати холод зовні, приймати дозволене знеболююче. Лікування: дренування гнійника, антисептична обробка, антибіотики за показаннями, лікування зуба."}},{q:["гіркота в роті","неприємний запах","смак крові"],a:{short:"Може свідчити про запалення ясен або карієс.",medium:"Гіркота або кров’янистий присмак часто через гінгівіт, пародонтит або карієс. Потрібна гігієна та лікування.",detailed:"Гіркота, запах або присмак крові у роті виникають при запаленні ясен (гінгівіт, пародонтит), розкладанні каріозної порожнини або проблемах із зубними відкладеннями. Тимчасово: полоскання теплою водою, зубна нитка, м’яка щітка. Остаточно: професійне чищення, лікування карієсу, усунення зубного нальоту та контроль гігієни."}},{q:["карієс","дірка","чорна точка","пляма"],a:{short:"Карієс — пошкодження зубної емалі.",medium:"Карієс буває поверхневий, середній та глибокий. На ранніх стадіях можлива ремінералізація.",detailed:"Карієс — це поступове руйнування емалі та дентину зуба через бактерії та кислоти. Поверхневий карієс лікується ремінералізацією, середній — пломбуванням, глибокий може потребувати лікування каналів. Профілактика: гігієна, фторовані пасти, контроль цукру в раціоні, регулярні огляди."}},{q:["глибокий карієс","велика дірка"],a:{short:"Глибокий карієс близький до нерва.",medium:"Потребує пломбування або лікування каналів, щоб зберегти зуб.",detailed:"Глибокий карієс вражає дентин і наближається до пульпи. Без лікування можливий пульпіт або абсцес. Сучасне лікування включає ізоляцію робочої зони, пломбування або ендодонтичне лікування (канали). Профілактика: регулярний огляд, своєчасне пломбування ранніх каріозних порожнин."}},{q:["біла пляма","демінералізація"],a:{short:"Біла пляма — перший сигнал карієсу.",medium:"Демінералізація емалі можливе лікування без свердління: ремінералізація та герметизація.",detailed:"На ранніх стадіях карієсу емаль втрачає мінерали, з’являється біла матова пляма. Лікування: ремінералізація фторвмісними гелями, герметизація фісур. Важливо підтримувати гігієну та регулярні огляди для запобігання прогресуванню."}},{q:["пульпіт","лікування каналів","канали"],a:{short:"Пульпіт — запалення нерва зуба.",medium:"Лікується дезінфекцією та пломбуванням каналів, що зберігає зуб.",detailed:"Пульпіт виникає при інфекції або глибокому карієсі, коли нерв зуба запалюється. Симптоми: пульсуючий біль, чутливість на гаряче/холодне. Лікування каналів включає очищення, дезінфекцію та пломбування кореневих каналів. Профілактика: своєчасне лікування карієсу, контроль гігієни та регулярні огляди."}},{q:["канал недопломбований","полікувати канали заново"],a:{short:"Повторне лікування каналів потрібне при болю чи інфекції.",medium:"Переліковування каналів дозволяє усунути запалення та зберегти зуб.",detailed:"Іноді канал недопломбований або з’являється нова інфекція. Сучасна мікроскопічна ендодонтія дозволяє повторно очистити та запломбувати канал, навіть у складних випадках. Важливо не затягувати, щоб уникнути видалення зуба. Профілактика: регулярний огляд після лікування каналів та дотримання гігієни."}},{q:["кровоточивість","кровоточать ясна"],a:{short:"Кровоточивість — ознака запалення ясен.",medium:"Може бути через гінгівіт або пародонтит. Потрібна професійна чистка.",detailed:"Кровоточивість ясен свідчить про запалення (гінгівіт або початковий пародонтит). Симптоми: почервоніння, набряк, наліт. Лікування: професійна гігієна (ультразвук, AirFlow), усунення зубного каменю, корекція догляду вдома. Профілактика: щоденне чищення, зубна нитка, огляд у стоматолога."}},{q:["опустилися ясна","рецесія","оголився корінь"],a:{short:"Рецесія ясен — оголення шийки зуба.",medium:"Може бути через неправильну чистку, тонкий біотип, пародонтит. Лікується гігієною та хірургічно.",detailed:"Рецесія ясен — зниження рівня ясен і оголення кореня. Причини: травматична чистка, тонкий біотип ясен, запальні процеси. Лікування: професійна гігієна, корекція техніки чищення, у складних випадках — хірургічна пластика ясен. Профілактика: щітки з м’якою щетиною, правильна техніка чищення, контроль гігієни."}},{q:["рухається зуб","хитається зуб"],a:{short:"Рухомість зубів — ознака пародонтиту.",medium:"Потребує негайного огляду та лікування для збереження зубів.",detailed:"Рухомість зубів зазвичай виникає при прогресуючому пародонтиті, коли кісткова тканина навколо зуба руйнується. Лікування: професійна чистка, видалення зубного каменю, терапія ясен, ортодонтична стабілізація зубів. Важливо не затягувати, щоб уникнути втрати зубів. Профілактика: регулярні огляди та контроль гігієни."}},{q:["видалення зуба","вирвати зуб"],a:{short:"Сучасне видалення зуба без болю.",medium:"Проводиться щадним методом з анестезією. Після процедури даються рекомендації для швидкого загоєння.",detailed:"Сучасна стоматологія дозволяє видаляти зуби мінімально травматично. Анестезія забезпечує комфорт, а після видалення пацієнт отримує рекомендації: уникати гарячого, не гріти рану, прикладати холод зовні, не полоскати перші 24 години. Це запобігає сухій лунці та ускладненням. Профілактика: регулярні огляди та лікування зубів до критичного стану."}},{q:["після видалення","що робити після видалення"],a:{short:"Перші години після видалення важливі для загоєння.",medium:"Не полоскати, не торкатися ранки, прикладати холод 10 хвилин, уникати фізичних навантажень та алкоголю.",detailed:"Щоб уникнути ускладнень після видалення зуба, дотримуйтесь рекомендацій: не торкайтеся ранки, не полощіть перші 24 години, прикладайте холод зовні 10 хвилин, уникати гарячого і алкоголю, обмежити фізичну активність. Це допомагає зберегти кров’яний згусток, який забезпечує швидке та безпечне загоєння."}},{q:["суха лунка","болить після видалення"],a:{short:"Суха лунка — ускладнення після видалення.",medium:"Виникає, коли кров’яний згусток вимився, спричиняє сильний пульсуючий біль. Потрібне повторне оброблення у лікаря.",detailed:"Суха лунка — це стан, коли кров’яний згусток не утримується у лунці після видалення зуба. Симптоми: сильний пульсуючий біль, неприємний запах. Лікування — професійна обробка лунки, нанесення спеціальних препаратів для загоєння. Профілактика: дотримання рекомендацій після видалення, уникання смоктання, полоскань та гарячих напоїв перші 24 години."}},{q:["зуб мудрості","видалення мудрості"],a:{short:"Треті моляри часто ростуть неправильно.",medium:"Можуть тиснути на сусідні зуби, викликати запалення. Видалення контрольоване та безпечне.",detailed:"Зуби мудрості часто ростуть під кутом або частково прорізуються, створюючи проблеми: тиск на сусідні зуби, запалення, біль, абсцеси. Сучасне видалення зубів мудрості виконується під місцевою анестезією з мінімальним травмуванням. Після процедури даються детальні рекомендації для швидкого загоєння."}},{q:["вініри","тонкі накладки"],a:{short:"Вініри покращують форму та колір зубів.",medium:"Композитні та керамічні. Керамічні довговічніші та природніші на вигляд.",detailed:"Вініри — тонкі накладки на передню поверхню зуба для корекції кольору, форми та симетрії. Композитні швидко встановлюються та менш дорогі, керамічні служать 10–15 років та максимально природні. Профілактика: дбайлива гігієна, уникання твердих предметів, регулярні огляди."}},{q:["відбілювання","білизна зубів","зробити зуби білішими"],a:{short:"Професійне відбілювання освітлює зуби на кілька тонів.",medium:"Безпечне при правильній підготовці та ремінералізації, ефект 2–8 тонів.",detailed:"Відбілювання зубів професійними методами дозволяє освітлити емаль на 2–8 тонів, залежно від техніки та початкового кольору. Попереднє лікування карієсу та ремінералізація емалі забезпечують безпечний результат. Тимчасова чутливість можлива, рекомендуються пасти для чутливих зубів та уникання гарячого/холодного протягом 24 годин."}},{q:["після відбілювання болить","чутливість після відбілювання"],a:{short:"Чутливість після процедури — нормальна реакція.",medium:"Тимчасова, зникає протягом 1–3 днів. Рекомендується ремінералізація та спеціальні пасти.",detailed:"Чутливість виникає через вплив відбілюючих агентів на емаль і дентин. Зазвичай проходить за 1–3 дні. Для зменшення симптомів використовують ремінералізуючі гелі та пасти для чутливих зубів. Рекомендовано уникати гарячого/холодного, кислих напоїв та механічного впливу на зуби перші дні."}},{q:["імплант","імплантація"],a:{short:"Імплант замінює втрачені зуби.",medium:"Титановий корінь, встановлюється замість зуба. Служить десятиліттями, планується під КТ.",detailed:"Імплант — штучний корінь із титану або цирконію, який встановлюється в кістку щелепи. Процедура включає планування під КТ, підбір системи та встановлення. Сучасна імплантологія дозволяє відновити як один зуб, так і повні ряди зубів. Профілактика: гігієна навколо імпланта, регулярні огляди, контроль навантаження."}},{q:["кісткова пластика","синус-ліфтинг"],a:{short:"Кісткова пластика необхідна при нестачі кістки.",medium:"Процедура дозволяє встановити імплант навіть у складних умовах.",detailed:"Кісткова пластика та синус-ліфтинг застосовуються, коли щелепна кістка недостатня для імплантації. Процедура безпечна, дозволяє наростити кістку, після загоєння встановлюється імплант. Контроль КТ та професійне планування гарантують успішний результат."}},{q:["імплант болить","почервоніння навколо імпланта"],a:{short:"Почервоніння або біль може бути ознакою запалення.",medium:"Мукозит або перімплантит. Легко лікується при своєчасному зверненні.",detailed:"Біль або почервоніння навколо імпланта можуть свідчити про мукозит (запалення ясен) або перімплантит (запалення кістки). Симптоми: набряк, чутливість, іноді гній. Лікування: професійне очищення, антисептики, корекція гігієни. Вчасне звернення гарантує збереження імпланта."}},{q:["брекети","вирівняти зуби"],a:{short:"Брекети — класичний метод корекції прикусу.",medium:"Ефективні для всіх вікових груп. Металеві, сапфірові, лінгвальні варіанти.",detailed:"Брекети застосовуються для виправлення прикусу та вирівнювання зубів. Металеві — міцні, сапфірові — естетичні, лінгвальні — непомітні з внутрішньої сторони. Процес включає встановлення, корекції та контроль результату. Профілактика: догляд за зубами та брекетами, регулярні візити до ортодонта."}},{q:["елайнери","прозорі капи","інвізалайн"],a:{short:"Елайнери — прозорі знімні капи для вирівнювання зубів.",medium:"Комфортні, знімні, підходять для більшості пацієнтів. Мінімально впливають на ротову гігієну.",detailed:"Елайнери — сучасна альтернатива брекетам. Серія прозорих кап змінюється кожні 1–2 тижні для поступового переміщення зубів. Переваги: естетика, знімність, зручність гігієни. Профілактика: носіння за графіком, догляд за капами, регулярні огляди у ортодонта."}},{q:["молочні зуби","лікувати дитячі зуби"],a:{short:"Молочні зуби лікуються для здоров’я постійних.",medium:"Впливають на прикус та розвиток щелепи, своєчасне лікування необхідне.",detailed:"Молочні зуби важливі для формування правильного прикусу та розвитку щелепи. Лікування включає пломбування, герметизацію та корекцію при потребі. Профілактика: регулярна гігієна, контроль харчування, відвідування стоматолога кожні 3–6 місяців."}},{q:["дитина боїться","страх стоматолога у дітей"],a:{short:"М’який адаптивний підхід для дітей.",medium:"Поступовий контакт, демонстрація інструментів, пояснення у формі гри.",detailed:"Діти часто бояться стоматолога через незнайомість та страх болю. Використовуються методи поступового адаптаційного контакту: показ інструментів, гра, пояснення процедур у легкій формі. Це формує довіру та зменшує стрес, полегшуючи лікування."}},{q:["герметизація","захист дитячих зубів"],a:{short:"Герметизація фісур — профілактика карієсу.",medium:"Безболісна, швидка процедура для захисту жувальних зубів у дітей.",detailed:"Герметизація фісур — нанесення спеціального захисного матеріалу на жувальні поверхні зубів. Це закриває щілини, де накопичується наліт і бактерії, запобігаючи карієсу. Процедура безболісна, швидка та ефективна. Профілактика: регулярний огляд, підтримка гігієни."}},{q:["чистка зубів","професійна гігієна","камінь"],a:{short:"Професійна чистка видаляє наліт та камінь.",medium:"Включає ультразвук, AirFlow, полірування та зміцнення емалі. Рекомендовано раз на 6 місяців.",detailed:"Професійна гігієна зубів — комплекс процедур: ультразвукове видалення каменю, піскоструйна чистка (AirFlow), полірування поверхні, ремінералізація та зміцнення емалі. Це запобігає карієсу, пародонтиту та неприємному запаху. Рекомендовано проводити раз на 6 місяців або частіше при схильності до нальоту."}},{q:["яку пасту","яку щітку","чим чистити"],a:{short:"Вибір залежить від стану зубів та ясен.",medium:"М’яка щітка, паста без агресивного абразиву, обов’язково флос або йоршики.",detailed:"Для чутливих зубів — м’яка щітка та пасти з ремінералізуючими компонентами. Для пацієнтів з імплантами чи брекетами — флос, йоршики, іригатор. Дотримання правильної техніки чистки та частота 2–3 рази на день мінімізує ризик карієсу та запалення ясен."}},{q:["запах з рота","галітоз"],a:{short:"Запах з рота часто пов’язаний з нальотом або карієсом.",medium:"Може бути через наліт, залишки їжі, карієс або запалення ясен. Гігієна + лікування проблемних ділянок вирішує проблему.",detailed:"Галітоз може мати локальні причини (наліт, карієс, запалення ясен) та системні (проблеми шлунково-кишкового тракту). Регулярна гігієна, професійна чистка, лікування карієсу та пародонтиту, промивання язика та використання ополіскувачів ефективно усувають запах. Важливо звернути увагу на харчування та здоров’я внутрішніх органів."}},{q:["перша допомога","зняти біль","що робити якщо"],a:{short:"Холод зовні та знеболююче тимчасово полегшують біль.",medium:"Уникайте жування на хвору сторону, полощіть теплою водою. Не гріти! Остаточне рішення — лікування у стоматолога.",detailed:"Для тимчасового полегшення зубного болю можна прикласти холод зовні, прийняти дозволене знеболююче, уникати жування на хвору сторону. Полоскання теплою водою або сольовим розчином допомагає зняти дискомфорт. Не використовувати тепло на ділянці запалення. Важливо: ці методи лише тимчасові, остаточне лікування забезпечить лікар."}},{q:["випала пломба","вилетіла пломба"],a:{short:"Уникайте жування на пошкоджену сторону.",medium:"Не закривайте отвір жувальною гумкою. Потрібне відновлення у стоматолога.",detailed:"Якщо пломба випала, не намагайтеся закрити отвір підручними засобами. Уникайте жування на пошкодженій ділянці та не закривайте її жувальною гумкою. Тимчасово можна застосувати стоматологічний тимчасовий матеріал, але для повного відновлення обов’язково зверніться до стоматолога."}},{q:["скол зуба","відколовся зуб"],a:{short:"Скол можна відновити композитом або коронкою.",medium:"Зберігайте уламок, якщо він є. Вчасне звернення дозволяє відновити форму зуба.",detailed:"В разі сколу зуба важливо зберегти уламок, якщо він є. Залежно від розміру та місця, стоматолог відновлює зуб композитним матеріалом або встановлює коронку. Це забезпечує естетику та функцію зуба. Важливо звернутися якнайшвидше, щоб уникнути ускладнень, таких як підвищена чутливість або запалення пульпи."}},{q:["вагітність","лікування при вагітності"],a:{short:"Гігієна та лікування безпечні при вагітності.",medium:"Можна проводити гігієну, лікування карієсу, рентген за потреби з захистом.",detailed:"Під час вагітності допустимо проводити професійну гігієну, лікування карієсу та невеликі хірургічні втручання під місцевою анестезією. Рентген можливий із захистом живота. Використовуються сучасні безпечні анестетики. Важливо контролювати гігієну рота, щоб уникнути запалення ясен, яке може вплинути на здоров’я матері та дитини."}},{q:["анестезія","заморозка"],a:{short:"Сучасна анестезія безпечна та ефективна.",medium:"Працює локально, швидко знімає біль, не впливає на організм в цілому.",detailed:"Місцева анестезія забезпечує безболісне лікування зубів. Використовуються сучасні препарати з коротким або середнім часом дії. Безпечні навіть для дітей та вагітних (залежно від триместру та дозування). Після процедури пацієнт відчуває лише тимчасове оніміння, без загального впливу на організм."}},{q:["знеболююче","які таблетки"],a:{short:"Стандартні знеболюючі можна застосовувати при відсутності протипоказань.",medium:"Допомагають тимчасово, але остаточно біль усувається лікуванням.",detailed:"Для тимчасового полегшення болю застосовують нестероїдні протизапальні препарати (НПЗП) або анальгетики. Важливо дотримуватися дозування та враховувати наявність протипоказань (алергія, хвороби шлунка, печінки, нирок). Це лише тимчасовий захід — остаточне усунення проблеми можливо лише через лікування у стоматолога."}},{q:["що робити","як бути","що тепер","що далі","як далі діяти"],a:{short:"Звертайтесь до лікаря для точного діагнозу.",medium:"Самостійні дії можуть бути небезпечні. Професійний огляд забезпечує правильне лікування.",detailed:"Не ризикуйте здоров’ям, намагайтеся не експериментувати з народними методами або самолікуванням. Огляд стоматолога дозволяє правильно діагностувати проблему, підібрати безпечне лікування та запобігти ускладненням. Використовуйте тимчасові заходи (знеболююче, холод), але плануйте візит до лікаря якнайшвидше."}}],n=document.getElementById("faq-list");a.forEach(t=>{const e=document.createElement("div");e.style.border="1px solid #ccc",e.style.borderRadius="8px",e.style.marginBottom="10px",e.style.padding="10px",e.style.cursor="pointer",e.style.transition="all 0.2s";const i=document.createElement("div");i.innerHTML=` ${t.q.join(", ")}`,i.style.fontSize="15px",i.style.color="#333",e.appendChild(i);const d=document.createElement("div");d.innerHTML=`
    <p><b>Коротко:</b> ${t.a.short}</p>
    <p><b>Середній:</b> ${t.a.medium}</p>
    <p><b>Детально:</b> ${t.a.detailed}</p>
  `,d.style.display="none",d.style.marginTop="8px",d.style.paddingTop="8px",d.style.borderTop="1px solid #eee",e.appendChild(d),e.onclick=()=>{d.style.display==="none"?(d.style.display="block",e.style.backgroundColor="#f9f9f9"):(d.style.display="none",e.style.backgroundColor="white")},n.appendChild(e)});document.addEventListener("DOMContentLoaded",()=>{const t=document.querySelector(".location-map");t&&(t.dataset.src||(t.dataset.src=t.src,t.src=""),new IntersectionObserver((i,d)=>{i.forEach(o=>{o.isIntersecting&&(t.src=t.dataset.src,d.unobserve(t))})},{threshold:.1}).observe(t))});
